import sys
MOD=998244353

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]
    p=[0]*(n+2)
    p[0]=n+1
    for i in range(1,len(data),2):
        p[data[i]]=data[i+1]
    dp=[0]*(n+2)
    dp[0]=1
    for b in range(1,n+2):
        low=p[b]
        total=0
        for a in range(b):
            high=p[a]
            if high<=low or dp[a]==0:
                continue
            vals=[p[k] for k in range(a+1,b) if low<p[k]<high]
            mx=0
            candidates=[]
            for v in reversed(vals):
                if v>mx:
                    candidates.append(v)
                    mx=v
            # An isolated point is both a prefix minimum and a suffix maximum.
            mn=n+2
            j=len(candidates)-1
            valid=True
            for v in vals:
                if j>=0 and v==candidates[j]:
                    j-=1
                    if v<mn:
                        valid=False
                        break
                if v<mn:
                    mn=v
            if valid:
                total+=dp[a]
        dp[b]=total%MOD
    print(dp[n+1])

if __name__=='__main__':
    main()

