import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]

    # limit[l][k]: smallest right endpoint of a condition at k
    # whose left endpoint is at least l. Endpoints are half-open.
    limit = [[n + 1] * n for _ in range(n)]
    for i in range(2, len(data), 3):
        l, r, x = data[i], data[i + 1], data[i + 2]
        l -= 1
        x -= 1
        if r < limit[l][x]:
            limit[l][x] = r
    for l in range(n - 2, -1, -1):
        a, b = limit[l], limit[l + 1]
        for k in range(l + 1, n):
            if b[k] < a[k]:
                a[k] = b[k]

    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # dp[l][r] is the valid permutation count divided by (r-l)!.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][i] = 1
    for length in range(1, n + 1):
        for l in range(n - length + 1):
            r = l + length
            row = dp[l]
            lim = limit[l]
            total = 0
            for k in range(l, r):
                if lim[k] > r:
                    total += row[k] * dp[k + 1][r]
            row[r] = total * inv[length] % MOD

    answer = dp[0][n]
    for i in range(2, n + 1):
        answer = answer * i % MOD
    print(answer)

if __name__ == '__main__':
    main()

