import sys
from collections import deque

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]
    deg = [0] * n
    for v in a:
        deg[v] += 1
    q = deque(i for i in range(n) if deg[i] == 0)
    dp = [None] * n
    while q:
        u = q.popleft()
        v = a[u]
        cur = dp[u]
        par = dp[v]
        if cur is None:
            if par is None:
                dp[v] = list(range(1, m + 1))
            else:
                for j in range(m):
                    par[j] = par[j] * (j + 1) % MOD
        else:
            s = 0
            for j in range(m):
                s = (s + cur[j]) % MOD
                cur[j] = s
            if par is None:
                dp[v] = cur
            else:
                for j in range(m):
                    par[j] = par[j] * cur[j] % MOD
        dp[u] = None
        deg[v] -= 1
        if deg[v] == 0:
            q.append(v)
    ans = 1
    for i in range(n):
        if deg[i] == 0:
            continue
        u = i
        prod = None
        while deg[u]:
            deg[u] = 0
            cur = dp[u]
            if cur is not None:
                if prod is None:
                    prod = cur
                else:
                    for j in range(m):
                        prod[j] = prod[j] * cur[j] % MOD
            u = a[u]
        ways = m if prod is None else sum(prod) % MOD
        ans = ans * ways % MOD
    print(ans)

if __name__ == '__main__':
    main()

