import sys

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    factors = {}

    for i, x in enumerate(a):
        p = 2
        while p * p <= x:
            if x % p == 0:
                k = 0
                while x % p == 0:
                    x //= p
                    k += 1
                if p not in factors:
                    factors[p] = [0] * (n - 1)
                factors[p][i] = k
            p += 1
        if x > 1:
            if x not in factors:
                factors[x] = [0] * (n - 1)
            factors[x][i] = 1

    answer = 1
    for p, exponents in factors.items():
        total = sum(exponents)
        powers = [1] * (total + 1)
        for j in range(total):
            powers[j + 1] = powers[j] * p % MOD

        # dp[h]: sum of weights of normalized prefixes ending at height h.
        dp = [1]
        for i, k in enumerate(exponents, 1):
            if k == 0:
                dp = [v * powers[h] % MOD for h, v in enumerate(dp)]
                continue

            new = [0] * (len(dp) + k)
            shifts = [1] * (k + 1)
            base = pow(p, i, MOD)
            for d in range(k):
                shifts[d + 1] = shifts[d] * base % MOD

            for h, v in enumerate(dp):
                if not v:
                    continue
                nxt = h + k
                new[nxt] = (new[nxt] + v * powers[nxt]) % MOD
                if h >= k:
                    nxt = h - k
                    new[nxt] = (new[nxt] + v * powers[nxt]) % MOD
                else:
                    # Lowering the minimum raises all i previous heights.
                    new[0] = (new[0] + v * shifts[k - h]) % MOD
            dp = new

        answer = answer * (sum(dp) % MOD) % MOD

    print(answer)


if __name__ == '__main__':
    main()

