from math import isqrt

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    a = data[1:1 + data[0]]
    m = max(a)
    spf = list(range(m + 1))
    for p in range(2, isqrt(m) + 1):
        if spf[p] == p:
            for v in range(p * p, m + 1, p):
                if spf[v] == v:
                    spf[v] = p
    grundy = [0] * (m + 1)
    for v in range(2, m + 1):
        grundy[v] = grundy[v // spf[v]] + 1
    result = 0
    for v in a:
        result ^= grundy[v]
    print('Anna' if result else 'Bruno')

