import sys
from math import gcd

def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n, budget = next(it), next(it)
    processes = []
    upper = 10**9
    for _ in range(n):
        a, p, b, q = next(it), next(it), next(it), next(it)
        if p*b > q*a:
            a, p, b, q = b, q, a, p
        upper = min(upper, budget*a//p)
        choices = [(k*b, k*q) for k in range(a//gcd(a,b))]
        processes.append((a,p,choices))

    def feasible(w):
        total = 0
        for a,p,choices in processes:
            best = ((w+a-1)//a)*p
            for capacity, cost in choices:
                remaining = w-capacity
                if remaining > 0:
                    cost += ((remaining+a-1)//a)*p
                if cost < best:
                    best = cost
                if remaining <= 0:
                    break
            total += best
            if total > budget:
                return False
        return True

    lo, hi = 0, upper+1
    while hi-lo > 1:
        mid = (lo+hi)//2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    print(lo)

if __name__ == '__main__':
    main()

