class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        m = len(s)

        depth = [0] * (m + 1)
        for x in range(2, m + 1):
            depth[x] = 1 + depth[x.bit_count()]
        eligible = [x for x in range(1, m + 1) if depth[x] < k]

        fact = [1] * (m + 1)
        for i in range(1, m + 1):
            fact[i] = fact[i - 1] * i % MOD
        invfact = [1] * (m + 1)
        invfact[m] = pow(fact[m], MOD - 2, MOD)
        for i in range(m, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD

        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = m - i - 1
                for target in eligible:
                    needed = target - prefix_ones
                    if needed < 0:
                        continue
                    if needed > remaining:
                        break
                    answer += fact[remaining] * invfact[needed] % MOD * invfact[remaining - needed] % MOD
                answer %= MOD
                prefix_ones += 1
        return answer

