import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    rows = [0] * n
    for k in range(m):
        u, v = data[2 + 2*k] - 1, data[3 + 2*k] - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduce the adjacency matrix over GF(2).
    pivots = []
    rank = 0
    for c in range(n):
        p = next((i for i in range(rank, n) if (rows[i] >> c) & 1), -1)
        if p == -1:
            continue
        rows[rank], rows[p] = rows[p], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> c) & 1):
                rows[i] ^= rows[rank]
        pivots.append(c)
        rank += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    ans = [0] * n
    offset = 2 if m and len(free) <= 58 else 0
    # Each bit represents one independent nullspace vector.
    for j, c in enumerate(free):
        ans[c] = 1 << (j + offset)
    for i, c in enumerate(pivots):
        for f in free:
            if (rows[i] >> f) & 1:
                ans[c] ^= ans[f]

    if any(x == 0 for x in ans):
        print('No')
    else:
        print('Yes')
        print(*ans)


if __name__ == '__main__':
    main()

