from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        remaining = list(range(1, n + 1))
        odd, even = (n + 1) // 2, n // 2
        answer = []
        previous = -1

        while remaining:
            m = len(remaining) - 1
            for i, value in enumerate(remaining):
                parity = value % 2
                if parity == previous:
                    continue

                o = odd - parity
                e = even - (1 - parity)
                needed_odd = m // 2 if parity else (m + 1) // 2
                if o != needed_odd:
                    continue

                count = fact[o] * fact[e]
                if k > count:
                    k -= count
                else:
                    answer.append(value)
                    remaining.pop(i)
                    odd, even = o, e
                    previous = parity
                    break
            else:
                return []

        return answer

