        result = ['0'] * n
        remainder = 0
        for i in range(m):
            for d in range(9, 0 if i == 0 else -1, -1):
                new_remainder = (remainder + d * weights[i]) % k
                if dp[i + 1] & (1 << ((-new_remainder) % k)):
