class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        m = (n + 1) // 2
        weights = [0] * m
        for i in range(m):
            j = n - 1 - i
            weights[i] = (powers[i] + powers[j]) % k if i != j else powers[i] % k

        full = (1 << k) - 1
        dp = [0] * (m + 1)
        dp[m] = 1
        for i in range(m - 1, -1, -1):
            mask = dp[i + 1]
            if mask == full:
                dp[i] = full
                continue
            reachable = 0
            for d in range(10):
                shift = d * weights[i] % k
                reachable |= ((mask << shift) | (mask >> (k - shift))) & full
            dp[i] = reachable

        result = ['0'] * n
        remainder = 0
        for i in range(m):
            for d in range(9, 0 if i == 0 else -1, -1):
                new_remainder = (remainder + d * weights[i]) % k
                if dp[i + 1] & (1 << ((-new_remainder) % k)):
                    result[i] = result[n - 1 - i] = str(d)
                    remainder = new_remainder
                    break
        return ''.join(result)

