class Solution:
    def makeStringGood(self, s: str) -> int:
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1
        answer = len(s)
        for target in range(1, max(counts) + 1):
            dp0 = dp1 = 0
            previous = 0
            for count in counts:
                new0 = min(dp0, dp1) + count
                deficit = max(target - count, 0)
                new1 = abs(count - target) + min(
                    dp0 - min(previous, deficit),
                    dp1 - min(max(previous - target, 0), deficit)
                )
                dp0, dp1 = new0, new1
                previous = count
            answer = min(answer, dp0, dp1)
        return answer

