class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)

        def occurrences(t):
            m = len(t)
            if not m:
                return range(n + 1)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        a, b, c = p.split('*')
        aa, bb, cc = occurrences(a), occurrences(b), occurrences(c)
        la, lb, lc = len(a), len(b), len(c)
        j = k = 0
        best = n + 1
        for start in aa:
            while j < len(bb) and bb[j] < start + la:
                j += 1
            if j == len(bb):
                break
            while k < len(cc) and cc[k] < bb[j] + lb:
                k += 1
            if k == len(cc):
                break
            best = min(best, cc[k] + lc - start)
        return best if best <= n else -1

