    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    for i in range(2, len(data), 3):
        x, y, z = data[i] - 1, data[i + 1] - 1, data[i + 2]
        graph[x].append((y, z))
        graph[y].append((x, z))
    del data
    a = [-1] * n
    for root in range(n):
        if a[root] != -1:
            continue
        a[root] = 0
        component = [root]
        combined = 0
        for u in component:
            au = a[u]
            for v, z in graph[u]:
                av = au ^ z
                if a[v] == -1:
                    a[v] = av
                    combined |= av
                    component.append(v)
                elif a[v] != av:
                    print(-1)
                    return
        if combined:
            vals = [a[u] for u in component]
            size = len(vals)
            mask = 0
            for b in range(combined.bit_length()):
                ones = sum((v >> b) & 1 for v in vals)
                if ones * 2 > size:
                    mask |= 1 << b
            if mask:
                for u in component:
                    a[u] ^= mask
    print(' '.join(map(str, a)))

