import sys


def solve(n, sa, sb):
    if sa == sb:
        return 0
    a = [i for i, c in enumerate(sa) if c == 49]
    b = [i for i, c in enumerate(sb) if c == 49]
    m = len(a)
    r = len(b)
    if r > m:
        return -1
    if r == 1:
        return max(abs(a[0] - b[0]), abs(a[-1] - b[0]))

    lower = max(abs(a[0] - b[0]), abs(a[-1] - b[-1]))
    if m == r:
        allowed = 3
        prev = b[0] - a[0]
        for i in range(1, m):
            d = b[i] - a[i]
            if d > prev:
                return -1
            if d == prev:
                allowed &= 1 << (d & 1)
            prev = d
        if not allowed:
            return -1
        return lower if allowed & (1 << (lower & 1)) else lower + 1

    gaps = [a[i + 1] - a[i] for i in range(m - 1)]
    bg = [b[i + 1] - b[i] for i in range(r - 1)]

    def check(k):
        p = 0
        parity = k & 1
        for j, g in enumerate(bg):
            x = b[j]
            y = b[j + 1]
            limit = x + k
            low = y - k
            while p < m - 1:
                if a[p] > limit:
                    return False
                h = gaps[p]
                if a[p + 1] >= low and (h > g or (h == g and ((x - a[p]) & 1) == parity)):
                    p += 1
                    break
                p += 1
            else:
                return False
            if a[p] > y + k:
                return False
        return True

    answer = 2 * n + 2
    for parity in range(2):
        lo = (lower - parity + 1) // 2
        hi = (n + 1 - parity) // 2
        if not check(2 * hi + parity):
            continue
        while lo < hi:
            mid = (lo + hi) // 2
            if check(2 * mid + parity):
                hi = mid
            else:
                lo = mid + 1
        answer = min(answer, 2 * lo + parity)
    return answer if answer < 2 * n + 2 else -1


