def main():
    read = sys.stdin.buffer.readline
    k = int(read())
    s = read().strip()
    t = read().strip()
    n, m = len(s), len(t)
    if abs(n - m) > k:
        print('No')
        return

    i = 0
    end = min(n, m)
    while i < end and s[i] == t[i]:
        i += 1
    if i == n == m:
        print('Yes')
        return

    # For each diagonal i-j, keep the farthest reachable source index.
    prev = {0: i}
    target = n - m
    missing = -10000000
    for edits in range(1, k + 1):
        cur = {}
        for d in range(max(-edits, -m), min(edits, n) + 1):
            x = max(prev.get(d, missing) + 1,
                    prev.get(d - 1, missing) + 1,
                    prev.get(d + 1, missing))
            x = min(x, n, m + d)
            y = x - d
            if x < 0 or y < 0:
                continue
            while x < n and y < m and s[x] == t[y]:
                x += 1
                y += 1
            if d == target and x == n:
                print('Yes')
                return
            cur[d] = x
        prev = cur
    print('No')


