class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        active = [i for i, value in enumerate(nums) if value > 0]
        if not active:
            return 0
        reachable = [1] * len(nums)
        masks = [(1 << (value + 1)) - 1 for value in nums]
        targets = [1 << value for value in nums]
        for k, (left, right, value) in enumerate(queries, 1):
            remaining = []
            for i in active:
                if left <= i <= right:
                    reachable[i] = (reachable[i] | (reachable[i] << value)) & masks[i]
                if not (reachable[i] & targets[i]):
                    remaining.append(i)
            active = remaining
            if not active:
                return k
        return -1

