class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        s = bytes(nums)
        z = [0] * n
        left = right = 0
        for k in range(1, n):
            v = min(right - k + 1, z[k - left]) if k <= right else 0
            while k + v < n and s[v] == s[k + v]:
                v += 1
            z[k] = v
            if k + v - 1 > right:
                left, right = k, k + v - 1

        answer = 0
        dp = [0] * (n + 1)
        for i in range(n - 2, 0, -1):
            good = z[i] >= i
            if good:
                answer += max(0, n - 2 * i)
            bound = min((n + i) // 2, 2 * i - 1) if good else (n + i) // 2
            x = s[i]
            for j in range(i + 1, n):
                if x == s[j]:
                    v = dp[j + 1] + 1
                    dp[j] = v
                    if j <= bound and v >= j - i:
                        answer += 1
                else:
                    dp[j] = 0
        return answer

