class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        pairs = [(a, b) for a in range(3) for b in range(3) if a != b]
        prevs = [[k for k, (x, y) in enumerate(pairs) if x != a and y != b] for a, b in pairs]
        dp = [cost[0][a] + cost[n - 1][b] for a, b in pairs]
        for i in range(1, n // 2):
            left, right = cost[i], cost[n - 1 - i]
            ndp = []
            for k, (a, b) in enumerate(pairs):
                p, q, r = prevs[k]
                ndp.append(left[a] + right[b] + min(dp[p], dp[q], dp[r]))
            dp = ndp
        return min(dp)

